// DESCRIPTION: Confirm inventory holds at least one cooked_mutton using a fresh count immediately before returning success.
async function checkInventoryForCookedMutton(bot) {
    if (bot.interrupt_code) return false;
    await wait(bot, 1);
    if (bot.interrupt_code) return false;

    const inv = getInventoryCounts(bot);
    if (inv == null) {
        log(bot, 'FAILED: could not read inventory');
        return false;
    }

    let count = Number(inv['cooked_mutton']) || 0;
    if (count < 1) {
        log(bot, 'FAILED: cooked_mutton missing or count is 0');
        return false;
    }

    await wait(bot, 1);
    if (bot.interrupt_code) return false;

    const invFinal = getInventoryCounts(bot);
    if (invFinal == null) {
        log(bot, 'FAILED: could not re-read inventory before return');
        return false;
    }

    count = Number(invFinal['cooked_mutton']) || 0;
    if (count < 1) {
        log(bot, 'FAILED: cooked_mutton not present at confirm (count < 1)');
        return false;
    }

    log(bot, `cooked_mutton present: ${count} available (>= 1 confirmed)`);
    return true;
}

// DESCRIPTION: Eat one cooked_mutton from inventory when available to restore hunger and enable healing at 1 HP.
async function eatCookedMutton(bot) {
    if (bot.interrupt_code) return;
    const hasMutton = await checkInventoryForCookedMutton(bot);
    if (bot.interrupt_code) return;
    if (!hasMutton) return;
    await consume(bot, 'cooked_mutton');
    if (bot.interrupt_code) return;
}

