// DESCRIPTION: Wear the best helmet, chestplate, leggings and boots in the inventory; returns how many pieces were equipped.
async function equipBestArmor(bot) {
    const tiers = ['netherite', 'diamond', 'iron', 'chainmail', 'golden', 'leather'];
    const inv = getInventoryCounts(bot);
    let n = 0;
    for (const slot of ['helmet', 'chestplate', 'leggings', 'boots']) {
        if (bot.interrupt_code) return n;
        const t = tiers.find(t => inv[`${t}_${slot}`]);
        if (t && await equip(bot, `${t}_${slot}`)) n++;
    }
    return n;
}

// DESCRIPTION: Craft and wear any missing helmet, chestplate, leggings and boots of material (iron, diamond, golden, leather); returns pieces worn.
async function craftArmorSet(bot, material = 'iron') {
    if (!(await ensureCraftingTable(bot))) return 0;
    for (const slot of ['helmet', 'chestplate', 'leggings', 'boots']) {
        if (bot.interrupt_code) return 0;
        if (!getInventoryCounts(bot)[`${material}_${slot}`]) await craftItem(bot, `${material}_${slot}`, 1);
    }
    return await equipBestArmor(bot);
}
